\begin{align*}
A_1 &= \frac{1}{2} \cdot 8 \cdot 10 \cdot \sin(20^\circ) - \frac{1}{18} \cdot 8^2 \cdot \pi 
&= 40\sin(20^\circ) - \frac{32\pi}{9},
